/*<<<SEAM:00-atoms.js>>>*/

/* ═══════════════════════════════════════════════════════════════════════════
   LUCKY SOUNDS · L0 ATOMS
   The smallest verifiable pieces. Nothing here reads a note, a scale or a
   clock; every function is a closed-form of one textbook equation and can be
   checked against that equation alone. Layers above may use only what is
   proved here.
   Sample rate arrives as an argument, never as a global: the same atom has to
   run at 48k in the worklet, at 44.1k in an export and at 8k in a test.
   ═══════════════════════════════════════════════════════════════════════════ */

var TAU = Math.PI * 2;

/* ── numbers ───────────────────────────────────────────────────────────── */
function clamp(x, a, b) { return x < a ? a : x > b ? b : x; }
function lerp(a, b, t) { return a + (b - a) * t; }
function dbToGain(db) { return Math.pow(10, db / 20); }
function gainToDb(g) { return 20 * Math.log10(Math.max(1e-12, g)); }
/* MIDI 69 = A4 = 440Hz. Kept as the ONLY place pitch becomes frequency so a
   tuning change is one edit, not a search. */
function mtof(m, a4) { return (a4 || 440) * Math.pow(2, (m - 69) / 12); }
function ftom(f, a4) { return 69 + 12 * Math.log2(f / (a4 || 440)); }

/* Denormal guard. Cheap: adding a tiny alternating offset costs one add and
   keeps IIR tails out of the subnormal range where some CPUs stall hard. */
var DENORM = 1e-20;

/* ── deterministic randomness ──────────────────────────────────────────────
   Every world in this engine must regrow identically from its seed, on any
   machine, in the worklet and in an offline render alike. Math.random() can
   never appear below this line. sfc32 is small, fast and passes PractRand;
   the splitmix64-ish seeding spreads a single integer across four words. */
function makeRng(seed) {
  var a = seed >>> 0, b = 0x9e3779b9, c = 0x243f6a88, d = 0xb7e15162;
  for (var i = 0; i < 12; i++) {
    /* mix the seed in before any value is drawn, else nearby seeds correlate */
    a = (a + 0x6d2b79f5) >>> 0;
    var t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    b = (b ^ ((t ^ (t >>> 14)) >>> 0)) >>> 0;
    var s = b; b = c; c = d; d = s;
  }
  return function rng() {
    a |= 0; b |= 0; c |= 0; d |= 0;
    var t = (((a + b) | 0) + d) | 0;
    d = (d + 1) | 0;
    a = b ^ (b >>> 9);
    b = (c + (c << 3)) | 0;
    c = (c << 21) | (c >>> 11);
    c = (c + t) | 0;
    return (t >>> 0) / 4294967296;
  };
}
/* helpers that read like intent at the call site */
function rInt(rng, n) { return Math.floor(rng() * n) % n; }
function rRange(rng, a, b) { return a + (b - a) * rng(); }
function rPick(rng, arr) { return arr[Math.floor(rng() * arr.length) % arr.length]; }
function rChance(rng, p) { return rng() < p; }
/* weighted pick over parallel arrays — the workhorse of every generator above */
function rWeighted(rng, items, weights) {
  var s = 0, i;
  for (i = 0; i < weights.length; i++) s += weights[i];
  if (s <= 0) return items[0];
  var t = rng() * s;
  for (i = 0; i < weights.length; i++) { t -= weights[i]; if (t <= 0) return items[i]; }
  return items[items.length - 1];
}

/* ── one-pole smoother ─────────────────────────────────────────────────────
   A parameter that jumps mid-block clicks. Every control that a human or a
   sequencer can move passes through one of these first. */
function Smooth(init, ms, sr) {
  this.v = init || 0; this.t = init || 0;
  this.a = Math.exp(-1 / (Math.max(0.01, ms || 5) * 0.001 * sr));
}
Smooth.prototype.set = function (x) { this.t = x; };
Smooth.prototype.snap = function (x) { this.t = this.v = x; };
Smooth.prototype.tick = function () {
  this.v = this.t + (this.v - this.t) * this.a + DENORM;
  return this.v;
};
/* m samples in one call, for control-rate callers — see ADSR.tickN. The cache
   keys on `a` too because AnalogVoice writes glide.a directly per patch. */
Smooth.prototype.tickN = function (m) {
  if (m <= 1) return this.tick();
  if (m !== this._m || this.a !== this._a) { this._m = m; this._a = this.a; this._am = Math.pow(this.a, m); }
  this.v = this.t + (this.v - this.t) * this._am + DENORM;
  return this.v;
};

/* ── DC blocker ────────────────────────────────────────────────────────────
   y[n] = x[n] - x[n-1] + R*y[n-1].  R near 1 puts the corner near DC.
   Nonlinear stages (tanh on an asymmetric wave, reed tables, rectifiers) all
   emit DC; unblocked it eats headroom silently and shows up only as a limiter
   that never opens. */
function DCBlock(sr) { this.x1 = 0; this.y1 = 0; this.R = 1 - TAU * 12 / sr; }
DCBlock.prototype.tick = function (x) {
  var y = x - this.x1 + this.R * this.y1 + DENORM;
  this.x1 = x; this.y1 = y; return y;
};
DCBlock.prototype.reset = function () { this.x1 = 0; this.y1 = 0; };

/* ── one-pole filters (TPT / trapezoidal, zero-delay) ──────────────────────
   g = tan(pi*fc/sr) is the bilinear prewarp: it makes the digital corner land
   on the analog corner instead of drifting flat near Nyquist. */
function OnePole(sr) { this.sr = sr; this.s = 0; this.G = 0.1; this.setHz(1000); }
OnePole.prototype.setHz = function (hz) {
  var g = Math.tan(Math.PI * clamp(hz, 1, this.sr * 0.49) / this.sr);
  this.G = g / (1 + g);
};
OnePole.prototype.lp = function (x) {
  var v = (x - this.s) * this.G, y = v + this.s;
  this.s = y + v + DENORM;
  return y;
};
OnePole.prototype.hp = function (x) { return x - this.lp(x); };
OnePole.prototype.reset = function () { this.s = 0; };

/* ── state variable filter (Zavalishin TPT, zero-delay) ────────────────────
   Three outputs from one solve, self-oscillates cleanly at high Q, and stays
   stable when the cutoff is swept at audio rate — which is the whole point:
   an envelope on a naive biquad blows up, and that blow-up is the reason so
   much browser audio ends up with static filters and a "MIDI" flatness. */
function SVF(sr) {
  this.sr = sr; this.ic1 = 0; this.ic2 = 0;
  this.g = 0.1; this.k = 1; this.a1 = 0; this.a2 = 0; this.a3 = 0;
  this.lp = 0; this.bp = 0; this.hp = 0;
  this.set(1000, 0.707);
}
SVF.prototype.set = function (hz, q) {
  this.g = Math.tan(Math.PI * clamp(hz, 5, this.sr * 0.492) / this.sr);
  this.k = 1 / Math.max(0.05, q);
  this.a1 = 1 / (1 + this.g * (this.g + this.k));
  this.a2 = this.g * this.a1;
  this.a3 = this.g * this.a2;
};
SVF.prototype.tick = function (x) {
  var v3 = x - this.ic2;
  var v1 = this.a1 * this.ic1 + this.a2 * v3;
  var v2 = this.ic2 + this.a2 * this.ic1 + this.a3 * v3;
  this.ic1 = 2 * v1 - this.ic1 + DENORM;
  this.ic2 = 2 * v2 - this.ic2 + DENORM;
  this.lp = v2; this.bp = v1; this.hp = x - this.k * v1 - v2;
  return v2;
};
SVF.prototype.reset = function () { this.ic1 = this.ic2 = 0; this.lp = this.bp = this.hp = 0; };

/* ── RBJ biquad ────────────────────────────────────────────────────────────
   Fixed-coefficient work only (fixed EQ curves, formant shells). Anything
   swept belongs in an SVF. Direct Form I: two more adds, far better numerical
   behaviour with 32-bit-ish coefficient error at low corner frequencies. */
function Biquad() { this.b0 = 1; this.b1 = 0; this.b2 = 0; this.a1 = 0; this.a2 = 0; this.x1 = 0; this.x2 = 0; this.y1 = 0; this.y2 = 0; }
Biquad.prototype.tick = function (x) {
  var y = this.b0 * x + this.b1 * this.x1 + this.b2 * this.x2 - this.a1 * this.y1 - this.a2 * this.y2 + DENORM;
  this.x2 = this.x1; this.x1 = x; this.y2 = this.y1; this.y1 = y;
  return y;
};
Biquad.prototype.reset = function () { this.x1 = this.x2 = this.y1 = this.y2 = 0; };
Biquad.prototype.norm = function (b0, b1, b2, a0, a1, a2) {
  this.b0 = b0 / a0; this.b1 = b1 / a0; this.b2 = b2 / a0;
  this.a1 = a1 / a0; this.a2 = a2 / a0; return this;
};
Biquad.prototype.peak = function (sr, hz, q, dbGain) {
  var A = Math.pow(10, dbGain / 40), w = TAU * clamp(hz, 5, sr * 0.49) / sr;
  var cw = Math.cos(w), al = Math.sin(w) / (2 * Math.max(0.05, q));
  return this.norm(1 + al * A, -2 * cw, 1 - al * A, 1 + al / A, -2 * cw, 1 - al / A);
};
Biquad.prototype.lowShelf = function (sr, hz, dbGain) {
  var A = Math.pow(10, dbGain / 40), w = TAU * clamp(hz, 5, sr * 0.49) / sr;
  var cw = Math.cos(w), sw = Math.sin(w), S = 1;
  var al = sw / 2 * Math.sqrt((A + 1 / A) * (1 / S - 1) + 2), tsa = 2 * Math.sqrt(A) * al;
  return this.norm(A * ((A + 1) - (A - 1) * cw + tsa), 2 * A * ((A - 1) - (A + 1) * cw), A * ((A + 1) - (A - 1) * cw - tsa),
    (A + 1) + (A - 1) * cw + tsa, -2 * ((A - 1) + (A + 1) * cw), (A + 1) + (A - 1) * cw - tsa);
};
Biquad.prototype.highShelf = function (sr, hz, dbGain) {
  var A = Math.pow(10, dbGain / 40), w = TAU * clamp(hz, 5, sr * 0.49) / sr;
  var cw = Math.cos(w), sw = Math.sin(w), S = 1;
  var al = sw / 2 * Math.sqrt((A + 1 / A) * (1 / S - 1) + 2), tsa = 2 * Math.sqrt(A) * al;
  return this.norm(A * ((A + 1) + (A - 1) * cw + tsa), -2 * A * ((A - 1) + (A + 1) * cw), A * ((A + 1) + (A - 1) * cw - tsa),
    (A + 1) - (A - 1) * cw + tsa, 2 * ((A - 1) - (A + 1) * cw), (A + 1) - (A - 1) * cw - tsa);
};
Biquad.prototype.bandpass = function (sr, hz, q) {
  var w = TAU * clamp(hz, 5, sr * 0.49) / sr, cw = Math.cos(w), sw = Math.sin(w);
  var al = sw / (2 * Math.max(0.05, q));
  return this.norm(al, 0, -al, 1 + al, -2 * cw, 1 - al);
};
Biquad.prototype.highpass = function (sr, hz, q) {
  var w = TAU * clamp(hz, 5, sr * 0.49) / sr, cw = Math.cos(w), sw = Math.sin(w);
  var al = sw / (2 * Math.max(0.05, q));
  return this.norm((1 + cw) / 2, -(1 + cw), (1 + cw) / 2, 1 + al, -2 * cw, 1 - al);
};
Biquad.prototype.lowpass = function (sr, hz, q) {
  var w = TAU * clamp(hz, 5, sr * 0.49) / sr, cw = Math.cos(w), sw = Math.sin(w);
  var al = sw / (2 * Math.max(0.05, q));
  return this.norm((1 - cw) / 2, 1 - cw, (1 - cw) / 2, 1 + al, -2 * cw, 1 - al);
};

/* ── two-pole resonator ────────────────────────────────────────────────────
   The unit of every modal instrument in this engine: bars, bells, membranes,
   drum shells, the bridged-T drum circuit. Poles placed by decay time rather
   than Q, because a physical mode is specified by how long it rings, and T60
   survives a pitch change where a Q does not. */
function Reson(sr) {
  this.sr = sr; this.y1 = 0; this.y2 = 0; this.a1 = 0; this.a2 = 0; this.amp = 1; this.ampC = 1;
}
Reson.prototype.set = function (hz, t60) {
  var f = clamp(hz, 0.5, this.sr * 0.495);
  var w = TAU * f / this.sr;
  /* r^(sr*t60) = 10^-3  ->  r = 10^(-3/(sr*t60)) */
  var r = Math.exp(-6.9077553 / (Math.max(0.0005, t60) * this.sr));
  if (r > 0.9999995) r = 0.9999995;
  this.a1 = 2 * r * Math.cos(w);
  this.a2 = -r * r;
  /* TWO normalisations, because a mode is driven two different ways and one
     constant cannot serve both:
       amp  — STRUCK. The impulse response of this filter peaks at 1/sin(w),
              so sin(w) in makes a peak of 1 out, whatever the decay time.
       ampC — BLOWN/BOWED/SCRAPED. Under continuous drive the steady gain is
              1/(1-r), so a long mode would build without limit; the extra
              (1-r) holds a 6-second cymbal mode at the same level as a
              60-millisecond one.
     Getting this wrong is silent: struck modes normalised the continuous way
     come out ~80dB down and read as "the synth is broken". */
  this.amp = Math.sin(w);
  this.ampC = Math.sin(w) * (1 - r);
};
Reson.prototype.tick = function (x) {
  var y = this.a1 * this.y1 + this.a2 * this.y2 + x + DENORM;
  this.y2 = this.y1; this.y1 = y;
  return y;
};
Reson.prototype.reset = function () { this.y1 = this.y2 = 0; };

/* ── allpass ───────────────────────────────────────────────────────────────
   First order: fractional-sample tuning of a delay line, and, chained, the
   dispersion that makes a stiff string inharmonic (a piano, not a rubber
   band). */
function AP1() { this.a = 0; this.x1 = 0; this.y1 = 0; }
AP1.prototype.tick = function (x) {
  var y = this.a * (x - this.y1) + this.x1 + DENORM;
  this.x1 = x; this.y1 = y; return y;
};
/* delay of d samples at DC — Thiran-style first order. Well behaved for
   d in roughly [0.1, 1.9]; outside that the pole crowds the unit circle and
   the interpolator rings. */
AP1.prototype.setDelay = function (d) { this.a = (1 - d) / (1 + d); };
AP1.prototype.reset = function () { this.x1 = this.y1 = 0; };

/* ── second-order allpass ──────────────────────────────────────────────────
   The dispersion filter a stiff string actually needs. A first-order allpass
   only varies its delay near Nyquist, so for a bass string — whose whole
   audible partial series sits below 2kHz — it does nothing at all; a piano
   built on one comes out perfectly harmonic, which is to say it comes out
   sounding like a synthesizer. A conjugate pole pair inside the band puts the
   delay transition where the partials are.

     H(z) = (a2 + a1 z^-1 + z^-2) / (1 + a1 z^-1 + a2 z^-2)
     pole at r*e^(±j*theta):  a1 = -2 r cos(theta),  a2 = r^2            */
function AP2() { this.a1 = 0; this.a2 = 0; this.x1 = 0; this.x2 = 0; this.y1 = 0; this.y2 = 0; }
AP2.prototype.setPole = function (r, theta) {
  var rr = clamp(r, 0, 0.9995);
  this.a1 = -2 * rr * Math.cos(theta); this.a2 = rr * rr;
};
AP2.prototype.tick = function (x) {
  var y = this.a2 * x + this.a1 * this.x1 + this.x2 - this.a1 * this.y1 - this.a2 * this.y2 + DENORM;
  this.x2 = this.x1; this.x1 = x; this.y2 = this.y1; this.y1 = y;
  return y;
};
AP2.prototype.reset = function () { this.x1 = this.x2 = this.y1 = this.y2 = 0; };
/* Phase delay in samples at w. A resonant loop tunes on PHASE delay, not
   group delay, and for this filter the two differ by an order of magnitude —
   using the wrong one puts the string an octave out. */
AP2.prototype.phaseDelay = function (w) {
  var a1 = this.a1, a2 = this.a2;
  var c1 = Math.cos(w), s1 = Math.sin(w), c2 = Math.cos(2 * w), s2 = Math.sin(2 * w);
  var nr = a2 + a1 * c1 + c2, ni = -(a1 * s1 + s2);
  var dr = 1 + a1 * c1 + a2 * c2, di = -(a1 * s1 + a2 * s2);
  var p = Math.atan2(ni, nr) - Math.atan2(di, dr);
  while (p > 0) p -= TAU;
  while (p < -TAU) p += TAU;
  return -p / w;
};
/* Phase delay of the TPT one-pole lowpass, which is H(z)=G(1+z^-1)/(1-(1-2G)z^-1).
   Counted because a string loop that ignores it plays flat, and worse at high
   notes where the loop is only a few dozen samples long. */
OnePole.prototype.phaseDelay = function (w) {
  var G = this.G, a = -(1 - 2 * G);
  var nr = G * (1 + Math.cos(w)), ni = -G * Math.sin(w);
  var dr = 1 + a * Math.cos(w), di = -a * Math.sin(w);
  var p = Math.atan2(ni, nr) - Math.atan2(di, dr);
  while (p > 0) p -= TAU;
  return -p / w;
};

/* ── delay line, fractional read ───────────────────────────────────────────
   Power-of-two mask: a modulo per sample on a hot loop is a real cost, and a
   mask cannot drift out of bounds when a modulation overshoots. */
function Delay(maxSamples) {
  var n = 1; while (n < maxSamples + 4) n <<= 1;
  this.buf = new Float32Array(n); this.mask = n - 1; this.w = 0;
}
Delay.prototype.write = function (x) { this.buf[this.w] = x; this.w = (this.w + 1) & this.mask; };
Delay.prototype.readInt = function (d) { return this.buf[(this.w - d) & this.mask]; };
/* linear interpolation: transparent enough for chorus/reverb, and its
   lowpass-with-delay behaviour is actually wanted on a BBD emulation */
Delay.prototype.read = function (d) {
  var i = Math.floor(d), f = d - i;
  var a = this.buf[(this.w - i) & this.mask], b = this.buf[(this.w - i - 1) & this.mask];
  return a + (b - a) * f;
};
/* 4-point cubic (Catmull-Rom): for a string loop, where a linear read is a
   per-lap lowpass that darkens the tone by an amount that changes with pitch */
Delay.prototype.read4 = function (d) {
  var i = Math.floor(d), f = d - i, m = this.mask, w = this.w;
  var y0 = this.buf[(w - i + 1) & m], y1 = this.buf[(w - i) & m];
  var y2 = this.buf[(w - i - 1) & m], y3 = this.buf[(w - i - 2) & m];
  var c0 = y1, c1 = 0.5 * (y2 - y0), c2 = y0 - 2.5 * y1 + 2 * y2 - 0.5 * y3;
  var c3 = 0.5 * (y3 - y0) + 1.5 * (y1 - y2);
  return ((c3 * f + c2) * f + c1) * f + c0;
};
Delay.prototype.clear = function () { this.buf.fill(0); this.w = 0; };

/* ── noise ─────────────────────────────────────────────────────────────────
   White from the shared rng so a render is reproducible; pink via Voss-
   McCartney (Paul Kellet's economical form) because acoustic excitation —
   breath, brush, bow, cymbal wash — is nowhere near white. */
function noiseWhite(rng) { return rng() * 2 - 1; }
function Pink() { this.b = [0, 0, 0, 0, 0, 0, 0]; }
Pink.prototype.tick = function (w) {
  var b = this.b;
  b[0] = 0.99886 * b[0] + w * 0.0555179;
  b[1] = 0.99332 * b[1] + w * 0.0750759;
  b[2] = 0.96900 * b[2] + w * 0.1538520;
  b[3] = 0.86650 * b[3] + w * 0.3104856;
  b[4] = 0.55000 * b[4] + w * 0.5329522;
  b[5] = -0.7616 * b[5] - w * 0.0168980;
  var out = b[0] + b[1] + b[2] + b[3] + b[4] + b[5] + b[6] + w * 0.5362;
  b[6] = w * 0.115926;
  return out * 0.11;
};

/* ── saturation ────────────────────────────────────────────────────────────
   Odd-symmetric, C1-continuous, cheaper than tanh and with a slightly softer
   knee — which is the useful difference on a filter drive. */
function satSoft(x) {
  if (x < -3) return -1; if (x > 3) return 1;
  var x2 = x * x;
  return x * (27 + x2) / (27 + 9 * x2);
}
/* asymmetric: a tube/transformer bias. Emits DC by construction — every user
   of this must sit in front of a DCBlock, and they do. */
function satAsym(x, bias) {
  var b = bias === undefined ? 0.12 : bias;
  return satSoft(x + b) - satSoft(b);
}
/* hard-ish ceiling for the master: nothing above may exceed 1.0 */
function satLimit(x) { return x < -1.5 ? -1 : x > 1.5 ? 1 : x - (4 / 27) * x * x * x; }

/* ── PolyBLEP oscillator ───────────────────────────────────────────────────
   A naive saw aliases into a metallic buzz that never leaves the mix; this
   corrects the discontinuity with a 2-sample polynomial band-limited step.
   Phase is kept in [0,1) rather than radians so the BLEP window is a plain
   comparison against dt. */
function polyBlep(t, dt) {
  if (t < dt) { t /= dt; return t + t - t * t - 1; }
  if (t > 1 - dt) { t = (t - 1) / dt; return t * t + t + t + 1; }
  return 0;
}
function Osc() { this.p = 0; this.dt = 0; this.tri = 0; }
Osc.prototype.setHz = function (hz, sr) { this.dt = clamp(hz, 0, sr * 0.5) / sr; };
Osc.prototype.step = function () { this.p += this.dt; if (this.p >= 1) this.p -= 1; };
Osc.prototype.saw = function () { return 2 * this.p - 1 - polyBlep(this.p, this.dt); };
Osc.prototype.pulse = function (width) {
  var w = clamp(width === undefined ? 0.5 : width, 0.02, 0.98);
  var p2 = this.p + (1 - w); if (p2 >= 1) p2 -= 1;
  var v = (this.p < w ? 1 : -1) + polyBlep(this.p, this.dt) - polyBlep(p2, this.dt);
  /* DC of a pulse is (2w-1); removing it here keeps PWM from pumping the
     filter envelope, which is what makes cheap PWM pads sound like a fan */
  return v - (2 * w - 1);
};
/* leaky-integrated pulse: band-limited triangle for free, and the leak is the
   HP that keeps the integrator from walking off */
Osc.prototype.triangle = function () {
  this.tri = this.tri * 0.9992 + this.pulse(0.5) * 4 * this.dt;
  return this.tri;
};
Osc.prototype.sine = function () { return Math.sin(TAU * this.p); };

/* ── envelopes ─────────────────────────────────────────────────────────────
   Analog-shaped: each segment is an RC approach toward a target BEYOND the
   destination, so attacks bend the way a real envelope generator's do rather
   than ramping linearly. Release always runs to true zero (a voice that ends
   at 1e-4 clicks when it is stolen). */
var ENV_A = 0, ENV_D = 1, ENV_S = 2, ENV_R = 3, ENV_OFF = 4;
function ADSR(sr) {
  this.sr = sr; this.v = 0; this.stage = ENV_OFF;
  this.aC = 0; this.dC = 0; this.rC = 0; this.sus = 0.7; this.rFade = 0.01;
  this.set(0.005, 0.15, 0.7, 0.3);
}
/* Coefficients are derived from the time the segment is ASKED for, not from a
   fudge factor. An attack aiming at 1.2 reaches 1.0 after ln(6) time
   constants; a decay or release that must fall 60dB needs ln(1000). Getting
   these from the geometry means "0.4s release" is 0.4 seconds on a scope. */
ADSR.prototype._c = function (t, n) { return Math.exp(-n / (Math.max(0.0002, t) * this.sr)); };
