      var s1 = w1 === 0 ? o1.saw() : w1 === 1 ? o1.pulse(pw) : w1 === 2 ? o1.triangle() : o1.sine();
      var s2 = w2 === 0 ? o2.saw() : w2 === 1 ? o2.pulse(pw) : w2 === 2 ? o2.triangle() : o2.sine();
      var sb = subW ? sub.pulse(0.5) : sub.triangle();
