      mod[4] = ops[4].tick(s4 * idx);
      var s3 = 0; for (q = 0; q < m3.length; q++) s3 += mod[m3[q]];
      mod[3] = ops[3].tick(s3 * idx);
      var s2 = 0; for (q = 0; q < m2.length; q++) s2 += mod[m2[q]];
      mod[2] = ops[2].tick(s2 * idx);
      var s1 = 0; for (q = 0; q < m1.length; q++) s1 += mod[m1[q]];
      mod[1] = ops[1].tick(s1 * idx);
      var s0 = 0; for (q = 0; q < m0.length; q++) s0 += mod[m0[q]];
