  this.vib = new LFO(sr, rng); this.vib.p = rng();
  this.drift = new LFO(sr, rng); this.drift.shape = 4; this.drift.setHz(0.7); this.drift.p = rng();
  this.nz = new OnePole(sr); this.nz.setHz(2400);
