/* Deep-merge a named preset onto its family's _base. Presets state only what
   they change; the base guarantees every field exists, so no render loop can
   meet an undefined. */
function getPatch(family, name) {
  var fam = PATCHES[family];
  if (!fam) return null;
  var base = fam._base, p = fam[name] || {}, out = {};
  /* Array.isArray, not instanceof: an array that crossed a realm boundary —
     structured-cloned into a worklet, handed over from a worker — fails an
     instanceof check and would be silently deep-copied as a plain object,
     losing .length and turning every indexed read into undefined. */
  function cloneVal(v) {
    if (Array.isArray(v)) { var a = []; for (var i = 0; i < v.length; i++) a.push(cloneVal(v[i])); return a; }
    if (v && typeof v === 'object') { var o = {}; for (var k in v) o[k] = cloneVal(v[k]); return o; }
    return v;
  }
  /* the patch remembers its own name, so a voice can look up a measured trim
     for it — a Kit gets a patch object and nothing else, and asking the
     caller to pass the name alongside it is how the two drift apart */
  out.__name = name;
  var k;
  for (k in base) out[k] = cloneVal(base[k]);
  for (k in p) {
    if (p[k] && typeof p[k] === 'object' && !Array.isArray(p[k]) && out[k] && typeof out[k] === 'object' && !Array.isArray(out[k])) {
      for (var q in p[k]) out[k][q] = cloneVal(p[k][q]);
    } else out[k] = cloneVal(p[k]);
  }
  /* drum kits carry an array of per-slot objects; a preset overriding one slot
     must not drop the other eleven */
  if (family === 'drumK' && p.slots) {
    for (var i = 0; i < out.slots.length; i++) if (p.slots[i]) for (var s in p.slots[i]) out.slots[i][s] = p.slots[i][s];
  }
  var tt = TONE_TRIM[family + '/' + name];
  out.toneTrim = tt ? tt[0] : 0;
  out.toneCurve = tt ? tt[1] : 0;
  return out;
}

/* ── the tone axis make-up, in dB per unit bend ────────────────────────────
   tone is only worth having if it is brightness at CONSTANT LOUDNESS. It is
   not, by nature: opening a ladder, hardening a mallet or moving a bow toward
   the bridge all put more energy into the air as well as more of it up high,
   and measured raw the axis swung up to 6.2dB — which would be a second
   volume control walking straight through the level calibration (RING 4), the
   leveller and the -19 LUFS invariant.
   These numbers are the meter's output, not a taste: tools/measure-tone.js
   renders each patch at tone 0.0 / 0.5 / 1.0 and reports the level swing, and
   the trim is half that swing per unit bend, applied at the voice's own output
   so it corrects the thing that caused it. test-02's tone section re-measures
   every one of them, so the table cannot rot the way a hand-written one does.
   A patch not listed trims by zero — the honest default for an engine whose
   axis does not move level (organ is tone-blind entirely; its drawbars are
   set before you play, not while you play). */
