  lydDom:      { n: 'Lydian dominant',   s: [0, 2, 4, 6, 7, 9, 10],       bright: 0.78, tension: 0.42, fam: 'dom' },
  altered:     { n: 'Altered',           s: [0, 1, 3, 4, 6, 8, 10],       bright: 0.10, tension: 0.86, fam: 'dom' },
