  pushed:   { swing: 0.05, push: -0.014, humanT: 0.007, humanV: 0.10, hum: 0.9,
              limb: { snare: -2 } },
  drag:     { swing: 0.18, push: 0.030, humanT: 0.016, humanV: 0.14, hum: 1.3,
              limb: { snare: 14, hatC: 2 } },
