/* the five developments, plus identity */
function developMotif(m, kind, rng, key) {
  var c = m.cell, out = [], i;
  switch (kind) {
    case 'transpose': {
      var by = rWeighted(rng, [1, 2, -1, -2, 3, -3, 4], [0.22, 0.20, 0.20, 0.16, 0.1, 0.08, 0.04]);
      for (i = 0; i < c.length; i++) out.push({ deg: c[i].deg + by, dur: c[i].dur, pos: c[i].pos, accent: c[i].accent });
      break;
    }
    case 'invert': {
      var axis = c[0].deg;
      for (i = 0; i < c.length; i++) out.push({ deg: axis - (c[i].deg - axis), dur: c[i].dur, pos: c[i].pos, accent: c[i].accent });
      break;
    }
    case 'retrograde': {
      var p = 0;
      for (i = c.length - 1; i >= 0; i--) { out.push({ deg: c[i].deg, dur: c[i].dur, pos: p, accent: c[i].accent }); p += c[i].dur; }
      break;
    }
    case 'augment': {
      var p2 = 0;
      for (i = 0; i < c.length; i++) { var d = Math.max(1, Math.round(c[i].dur * 1.5)); out.push({ deg: c[i].deg, dur: d, pos: p2, accent: c[i].accent }); p2 += d; }
      break;
    }
    case 'fragment': {
      /* take a piece and SEQUENCE it — say it, then say it again a step up.
         This is the most recognisable device in tonal music and it costs six
         lines. */
      var n = Math.max(2, Math.min(c.length, 2 + rInt(rng, 2)));
      var start = rInt(rng, Math.max(1, c.length - n + 1));
      var p3 = 0, seqBy = rChance(rng, 0.5) ? 1 : -1;
      for (var rep = 0; rep < 2; rep++) {
        for (i = start; i < start + n && i < c.length; i++) {
          out.push({ deg: c[i].deg + rep * seqBy, dur: c[i].dur, pos: p3, accent: c[i].accent });
          p3 += c[i].dur;
        }
      }
      break;
    }
    default:
      for (i = 0; i < c.length; i++) out.push({ deg: c[i].deg, dur: c[i].dur, pos: c[i].pos, accent: c[i].accent });
  }
  var span = 0;
  for (i = 0; i < out.length; i++) span = Math.max(span, out[i].pos + out[i].dur);
  return { cell: out, span: span, len: out.length };
}

/* ── phrase plan ───────────────────────────────────────────────────────────
   A line is phrased in 4-bar units: two bars of STATEMENT, two of ANSWER.
   The plan decides, once per phrase, which bars breathe. Rests land on bar 3
   first — after the answer has arrived, so the arrival rings into the gap —
   and on bar 1 second (a one-bar statement is a question too; a rest on bar
   0 or 2 would silence the question or the answer themselves, which is not
   breathing, it is absence). Shaped by tension: play-2-rest-1 territory when
   the music is low, near-continuous at the peaks. `sparser` is for counter
   lines, which sit against the lead and need more air than it does. */
function phrasePlan(tension, rng, sparser) {
  var r3 = clamp((sparser ? 1.15 : 1.05) - 1.25 * tension, 0, 0.92);
  var r1 = sparser ? clamp(0.75 - 0.6 * tension, 0, 0.75) : clamp(0.55 - 0.55 * tension, 0, 0.55);
  return { rest: [false, rChance(rng, r1), false, rChance(rng, r3)] };
}

/* Snap a developed motif onto the chord under it. The rule real writers use:
   the notes on STRONG beats have to belong to the chord; the ones between can
   be anything the scale offers, and those are what make it a melody rather
   than an arpeggio. */
function fitToChord(cellNote, key, chordPcs, weight, rng) {
  var p = key.pitch(cellNote.deg, 0);
  if (weight < 0.5 || !chordPcs.length) return cellNote.deg;
  var pc = ((p % 12) + 12) % 12;
  for (var i = 0; i < chordPcs.length; i++) if (chordPcs[i] === pc) return cellNote.deg;
  /* move to the nearest chord tone, preferring the direction the line was
     already going. Searched one degree out first, two only if there is
     nothing closer: a wide search turns every correction into a leap. */
  var bestDeg = cellNote.deg, bd = 99;
  for (var d = cellNote.deg - 1; d <= cellNote.deg + 1; d++) {
    var q1 = ((key.pitch(d, 0) % 12) + 12) % 12;
    for (i = 0; i < chordPcs.length; i++) if (chordPcs[i] === q1) {
      var dist1 = Math.abs(d - cellNote.deg) + (d < cellNote.deg ? 0.1 : 0);
      if (dist1 < bd) { bd = dist1; bestDeg = d; }
    }
  }
  if (bd < 99) return bestDeg;
  for (d = cellNote.deg - 2; d <= cellNote.deg + 2; d++) {
    var q = ((key.pitch(d, 0) % 12) + 12) % 12;
    for (i = 0; i < chordPcs.length; i++) {
      if (chordPcs[i] === q) {
        var dist = Math.abs(d - cellNote.deg) + (d < cellNote.deg ? 0.1 : 0);
        if (dist < bd) { bd = dist; bestDeg = d; }
      }
    }
  }
  return bestDeg;
}

/* ── arrangement ───────────────────────────────────────────────────────────
   The form, and the tension curve that runs through it. Every section names
   its own tension, and tension is then read by everything: how dense the
   drums are, how far the filters open, how many notes the chords carry, how
   high the lead sits, how much reverb. One curve, many parameters — which is
   why an arrangement built this way rises and falls together instead of
   having each part rise on its own schedule. */
var SECTION_PLANS = {
  ballad:   [['intro',4,0.15],['A',8,0.38],['B',8,0.55],['A2',8,0.45],['C',8,0.78],['A3',8,0.52],['out',4,0.16]],
  drive:    [['intro',4,0.22],['A',8,0.52],['B',8,0.72],['A2',8,0.60],['drop',8,0.92],['A3',8,0.66],['out',4,0.20]],
  cycle:    [['intro',2,0.18],['A',8,0.42],['A2',8,0.56],['B',8,0.74],['A3',8,0.62],['out',2,0.14]],
  arc:      [['intro',6,0.12],['A',10,0.34],['B',10,0.58],['C',12,0.86],['A2',10,0.46],['out',6,0.14]],
  pulse:    [['intro',4,0.30],['A',8,0.58],['B',4,0.40],['A2',8,0.70],['drop',8,0.95],['A3',8,0.62],['out',4,0.22]],
  suite:    [['intro',4,0.14],['A',8,0.40],['B',8,0.62],['C',8,0.36],['D',8,0.80],['A2',8,0.50],['out',4,0.16]]
};
var SECTION_KEYS = Object.keys(SECTION_PLANS);

/* which roles are playing in a section, as a function of tension. A part that
   plays through everything has nowhere to go; entries and exits ARE the
   arrangement. */
/* `streamFor`, when given, hands back a stream belonging to ONE roster entry.
   Without it every part's entrance is drawn from a single stream in roster
   order, so adding, removing or reordering a part re-decides the arrangement
   for all the parts after it — which is exactly what promoting one
   instrument must never do. */
function rolesFor(section, tension, roster, rng, streamFor) {
  var on = {};
  for (var i = 0; i < roster.length; i++) {
    var r = roster[i], p, rr = streamFor ? streamFor(r) : rng;
    switch (r.role) {
      case 'kit':     p = section.name === 'intro' ? 0.35 : (tension > 0.25 ? 1 : 0.5); break;
      case 'perc':    p = section.name === 'intro' ? 0.3 : clamp(0.25 + tension * 0.9, 0, 1); break;
      case 'bass':    p = section.name === 'intro' ? 0.45 : (tension > 0.2 ? 0.98 : 0.7); break;
      case 'chord':   p = 0.62 + tension * 0.4; break;
      case 'pad':     p = 0.78 - tension * 0.18; break;
      case 'lead':    p = section.name === 'intro' || section.name === 'out' ? 0.22 : clamp(tension * 1.5 - 0.12, 0, 1); break;
      case 'counter': p = clamp(tension * 1.25 - 0.15, 0, 0.92); break;
      case 'arp':     p = clamp(tension * 1.35 - 0.06, 0, 1); break;
      case 'bell':    p = 0.30 + tension * 0.28; break;
      case 'texture': p = 0.55 - tension * 0.25; break;
      default:        p = 0.6;
    }
    on[r.id] = rChance(rr, clamp(p, 0, 1)) ? 1 : 0;
  }
  /* something must always be carrying the harmony, or a section falls out of
     the piece entirely */
  var any = false;
  for (i = 0; i < roster.length; i++) if (on[roster[i].id] && (roster[i].role === 'chord' || roster[i].role === 'pad')) any = true;
  if (!any) for (i = 0; i < roster.length; i++) if (roster[i].role === 'chord' || roster[i].role === 'pad') { on[roster[i].id] = 1; break; }
  return on;
}


