/* ═══════════════════════════════════════════════════════════════════════════
   LUCKY SOUNDS · L3b STYLES
   A world used to be one seven-scalar climate, and a climate can make a place
   but it cannot make a GENRE. Nothing in "dark, heavy, slow" says whether the
   bass plays the downbeat or refuses it, whether the timeline is a bell or a
   clave, whether the piano comps in a montuno or stabs on the offbeat — and
   those are the decisions that separate one music from another.

   So a style is a complete recipe, and it is the top-level decision: it picks
   the metre, the timeline, the kit, the instruments each role may use, how
   the bass relates to the kick, how the harmony behaves, and what the mix
   does. The climate still runs underneath and decides everything inside those
   choices, so two afrobeat worlds are as different from each other as two
   forests are — but neither one comes out as a drum machine demo.
   ═══════════════════════════════════════════════════════════════════════════ */

/* Layer helpers. A production keyboard patch is two or three sounds stacked,
   and this is where that gets said. `d` is detune in cents, `o` an octave
   offset, `p` a pan offset, `l` a level. */
function L1(e, pt, o) { var x = { engine: e, patch: pt, detune: 0, oct: 0, level: 1, pan: 0, spread: 7, panSpread: 0.2 }; for (var k in o) x[k] = o[k]; return [x]; }
function L2(a, ap, b, bp, o) {
  o = o || {};
  return [
    { engine: a, patch: ap, detune: -(o.d === undefined ? 7 : o.d), oct: o.o1 || 0, level: o.l1 === undefined ? 1 : o.l1, pan: -(o.p === undefined ? 0.16 : o.p), spread: o.spread === undefined ? 6 : o.spread, panSpread: 0.16 },
    { engine: b, patch: bp, detune: (o.d === undefined ? 7 : o.d), oct: o.o2 || 0, level: o.l2 === undefined ? 0.78 : o.l2, pan: (o.p === undefined ? 0.16 : o.p), spread: o.spread === undefined ? 6 : o.spread, panSpread: 0.16 }
  ];
}
function L3(a, ap, b, bp, c, cp, o) {
  o = o || {};
  return [
    { engine: a, patch: ap, detune: -(o.d === undefined ? 9 : o.d), oct: o.o1 || 0, level: o.l1 === undefined ? 1 : o.l1, pan: -(o.p === undefined ? 0.22 : o.p), spread: 6, panSpread: 0.15 },
    { engine: b, patch: bp, detune: 0, oct: o.o2 || 0, level: o.l2 === undefined ? 0.7 : o.l2, pan: 0, spread: 5, panSpread: 0.1 },
    { engine: c, patch: cp, detune: (o.d === undefined ? 9 : o.d), oct: o.o3 === undefined ? 1 : o.o3, level: o.l3 === undefined ? 0.42 : o.l3, pan: (o.p === undefined ? 0.22 : o.p), spread: 6, panSpread: 0.15 }
  ];
}

