  /* the gospel walk-up's bass: it ASCENDS BY STEP under the passing
     diminished, which is the half of the walk-up nobody writes down */
  walkGosp:    { hits: 'quarter',  tone: ['root', '5'],                       approach: 'step',      antic: 0, walkUp: 1 },
  /* the tumbao: it does not play the downbeat. TUMBAO_16 (06-rhythm) puts it
     on the "and of two" and the "four", and the four IS the anticipation */
  tumbao:      { hits: 'tumbao',   tone: ['5', 'root'],                       approach: null,        antic: 0.85 },
  /* Gilberto's thumb: root on one, fifth on three, the change announced on
     the and-of-four before the bar line it belongs to */
  bossaThumb:  { hits: 'bossa',    tone: ['root', '5'],                       approach: null,        antic: 0.75 },
  funk16:      { hits: 'funk16',   tone: ['root', 'b7', 'oct', 'b3'],         approach: 'ghost',     antic: 0.10, ghost: 0.35 },
  funk16Drag:  { hits: 'funk16',   tone: ['root', 'b7', 'oct', 'b3'],         approach: 'ghost',     antic: 0.10, ghost: 0.35, push: -0.035 },
  sub808:      { hits: 'sparse',   tone: ['root', 'b7', '5', 'oct'],          approach: null,        antic: 0,    slideP: 0.22 },
  sub808Slide: { hits: 'sparse',   tone: ['root', 'b3', '5', 'oct', 'b7'],    approach: null,        antic: 0,    slideP: 0.50, slideMax: 3 },
  /* A7 vs §7b: the design's table says antic 0 and A7 demands >=70%. A7 wins,
     and the musical reading that makes it survivable is the one k05 already
     wrote down — the log drum lands BETWEEN the kicks, which is where an
     anticipation lives anyway. Marked, because a number changed to satisfy a
     test is a number that owes a listen. */
  logDrum:     { hits: 'between',  tone: ['root', 'b3', '5', 'oct'],          approach: null,        antic: 0.75, never: 'onKick' },
  rootLong:    { hits: 'one',      tone: ['root'],                            approach: null,        antic: 0,    dur: 'bar' },
  dubMelody:   { hits: 'sparse',   tone: ['root', '5', 'b7', 'oct'],          approach: 'step',      antic: 0,    rests: 0.4, phrase: 2 },
  /* the bolon — the three-string Malinké bass harp, and the marímbula that
     replaced it across the Caribbean. Roots and fifths on the strong points
     of the cycle, and the push that announces the turn. */
  bolon:        { hits: 'ternary', tone: ['root', '5', 'root', 'oct'], approach: null, antic: 0.6 },
  tuba:        { hits: 'oompah',   tone: ['root', '5'],                       approach: 'step',      antic: 0.2 },
  octaveHook:  { hits: 'hook',     tone: ['root', 'oct'],                     approach: null,        antic: 0 },
  pedal:       { hits: 'one',      tone: ['pedal'],                           approach: null,        antic: 0,    dur: 'section' }
