/* the seed picks ONE band and keeps it. Draws from the world stream, not a
   part stream: a band is a property of the world, and letting each role draw
   its own instrument is precisely the failure A9 counts. */
function pickEnsemble(tongueId, rng) {
  var E = ENSEMBLES[tongueId];
  if (!E) return null;
  var names = Object.keys(E);
  if (!names.length) return null;
  var pick = names[rInt(rng, names.length)];
  var band = E[pick];
  return { name: pick, band: band, credit: band.credit };
}

