/* ── FLETCHER-MUNSON, GENERALISED ──────────────────────────────────────────
   k05's KVOL_SLOPE is keyed on LANE, because a drum lane has a fixed
   spectral home: a kick is always a kick. A melodic part has none — a pad
   may sit at MIDI 55 in one world and 80 in another — so the slope has to be
   a function of the part's actual BAND CENTRE and not of its name.

   Source is the same: ISO 226 equal-loudness contours, the dB spent per phon
   of felt loudness change across the 40->80 phon span. The contours crowd
   together at low frequency (at ~55 Hz the span covers ~28 dB, 0.71 dB per
   phon), open to 40 dB at 1 kHz by definition, and stretch slightly at the
   3-5 kHz ear-canal resonance.

   THREE ANCHORS ARE MEASURED AND FIVE ARE INTERPOLATED, and the five are
   marked: 55, 1000 and 4000 Hz are the readings K5 shipped as sub, snare and
   hat; the rest interpolate the same curve and are what A10b replaces with
   readings off the ISO 226:2003 table. Marked is the only honest state for a
   number that has not been measured. */
var PHON_SLOPE = [
  [55, 0.72],     /* MEASURED — K5's sub row   */
  [110, 0.78],    /* interpolated              */
  [220, 0.86],    /* interpolated              */
  [440, 0.94],    /* interpolated              */
  [1000, 1.00],   /* MEASURED — 40 dB by definition */
  [2000, 1.03],   /* interpolated              */
  [4000, 1.05],   /* MEASURED — K5's hat row   */
  [8000, 1.00]    /* interpolated              */
];
function pVolSlope(bandLoMidi, bandHiMidi) {
  var f = mtof((bandLoMidi + bandHiMidi) * 0.5);
  if (f <= PHON_SLOPE[0][0]) return PHON_SLOPE[0][1];
  var n = PHON_SLOPE.length;
  if (f >= PHON_SLOPE[n - 1][0]) return PHON_SLOPE[n - 1][1];
  for (var i = 1; i < n; i++) {
    if (f > PHON_SLOPE[i][0]) continue;
    /* LOG-frequency interpolation, because the contours are drawn on a log
       axis and a linear read between 55 Hz and 110 Hz would put the midpoint
       an octave wrong */
    var t = Math.log(f / PHON_SLOPE[i - 1][0]) / Math.log(PHON_SLOPE[i][0] / PHON_SLOPE[i - 1][0]);
    return lerp(PHON_SLOPE[i - 1][1], PHON_SLOPE[i][1], t);
  }
  return 1;
}
/* the same fader law k05 shipped, keyed on the band instead of the lane. The
   fader rides event velocity in the score and not part level — a drummer
   playing quieter plays SOFTER, and the same is true of every player, so
   velocity opens and closes timbre for free and the world stays dice-pure
   so a LOCK captures the unfaded part. NO LOUDNESS COMPENSATION: the fader
   SPENDS the curve, it does not hide it. +-9 phon throw, mid 15 of 30
   (10 phons is roughly half or double loudness, Stevens' law). */
/* three statements, not one `var a = 1, b = 2, c = 3;` — the bundle's symbol
   scan reads `^var NAME` only as far as the first `=`, so every declarator
   after the first is built and never exported, and the failure is invisible
   until something outside this file asks for it. 05c-shapes hit it on its
   first run with LIL_LO/LIL_HI and wrote it down; this is the same trap. */
var PVOL_MID = 15;
var PVOL_MAX = 30;
var PVOL_PHON = 9;
function pRoleGain(band, v) {
  if (v === undefined || v === null || !band) return 1;
  v = Math.max(0, Math.min(PVOL_MAX, v | 0));
  if (v === PVOL_MID) return 1;
  var phon = (v - PVOL_MID) / PVOL_MID * PVOL_PHON;
  return Math.pow(10, phon * pVolSlope(band[0], band[1]) / 20);
}

/* ── the tables check themselves ───────────────────────────────────────────
   GRAMMARS §12 asks for a LOAD-TIME ASSERTION on the register plan. It is a
   returned list and not a throw, and the reason is the one 05c already gives
   for chordFromRoot falling back to a major triad: this runs inside a page
   with no console anybody will read, and a table note that nothing looks at
   is a bad day, while an exception at load is a silent world. So the check
   is a function, the test runs it and fails on it, and the page never calls
   it. That is the same trade `flipSelfTest` makes one file down.

   What it convicts:
     · a cell, bass grammar, line grammar, voice pool, ensemble or register
       row a tongue names that does not exist;
     · an ensemble naming a patch PATCHES does not have — or naming
       ['fm','fmBass'], which RING 18 banned outright;
     · a voicing grammar `voiceTongue` has no case for;
     · a chord band with no ROOM for the tongue's own voicing. GRAMMARS §12
       states this as "shellA needs its lowest note >= MIDI 53" and then
       hands neosoul a chord band of [48,74], so the design contradicts
       itself here. The resolution is the one the grammar already implements:
       voiceTongue floors every shell at max(lo, 53) itself, so a band whose
       low end sits under the floor is not a lie, it is a band whose bottom
       octave belongs to the pool's other voicings — `openTri` floors at 45,
       `quart` at 56. What WOULD convict is a band with no room above the
       floor, and that is what is checked. The low ends that sit under it are
       reported as notes, so the gap stays visible rather than being argued
       away.
     · a `devs` verb neither FLIPS nor developMotif knows. */
var DEV_VERBS = { same: 1, retro: 1, invert: 1, axisInvert: 1, mirrorTime: 1, augment: 1,
  rotate: 1, interversion: 1, intervalScale: 1, modalShift: 1, contour: 1, phase: 1,
  canon: 1, transpose: 1, fragment: 1, sequence: 1, retrograde: 1 };
var VOICE_GRAMS = { lead: 1, shellA: 1, shellB: 1, quart: 1, drop2: 1, drop24: 1, par3: 1,
  par6: 1, par4: 1, spread: 1, block: 1, openTri: 1, pow: 1, cluster: 1, triadOver: 1,
  montuno: 1, dyad37: 1, organTrio: 1 };
function tongueTableCheck() {
  var bad = [], ids = TONGUE_KEYS, i, j, k;
  for (i = 0; i < ids.length; i++) {
    var id = ids[i], T = TONGUES[id], nm = 'TONGUES.' + id;
    var cells = [T.cell, T.cellAlt, T.cellThird, T.cellRare].concat(T.cellPool || []);
    for (j = 0; j < cells.length; j++) if (cells[j] && !CHANGES[cells[j]] && !CHANGES12[cells[j]])
      bad.push(nm + ' names cell ' + cells[j] + ', which is in neither CHANGES nor CHANGES12');
    if (!BASS[T.bass]) bad.push(nm + '.bass -> BASS.' + T.bass + ' missing');
    if (!LINES[T.line]) bad.push(nm + '.line -> LINES.' + T.line + ' missing');
    if (!VOICE_POOL[T.pool]) bad.push(nm + '.pool -> VOICE_POOL.' + T.pool + ' missing');
    if (!ENSEMBLES[T.ens]) bad.push(nm + '.ens -> ENSEMBLES.' + T.ens + ' missing');
    if (!REG[T.reg]) bad.push(nm + '.reg -> REG.' + T.reg + ' missing');
    for (k in T.voice) if (!VOICE_GRAMS[T.voice[k]]) bad.push(nm + '.voice.' + k + ' = ' + T.voice[k] + ', which voiceTongue has no case for');
    var pool = VOICE_POOL[T.pool] || [];
    for (j = 0; j < pool.length; j++) if (pool[j] !== null && !VOICE_GRAMS[pool[j]])
      bad.push('VOICE_POOL.' + T.pool + ' names ' + pool[j] + ', which voiceTongue has no case for');
    for (j = 0; j < (T.devs || []).length; j++) if (!DEV_VERBS[T.devs[j]])
      bad.push(nm + '.devs names ' + T.devs[j] + ', which neither FLIPS nor developMotif knows');
    var R = REG[T.reg];
    if (R) {
      var shelly = T.voice.chord === 'shellA' || T.voice.chord === 'shellB' ||
                   pool.indexOf('shellA') >= 0 || pool.indexOf('shellB') >= 0;
      if (shelly && R.chord[1] < 53 + 12) bad.push(nm + ' voices shells but REG.' + T.reg + '.chord tops out at ' + R.chord[1] + ', leaving no room above the shell floor of 53');
      if (shelly && R.chord[0] < 53) bad.push('note: REG.' + T.reg + '.chord starts at ' + R.chord[0] + ', below the shell floor of 53 — voiceTongue clamps, so that octave is the pool\'s other voicings');
      if (T.voice.top === 'cluster' && R.lead[1] < 72) bad.push(nm + ' voices a cluster but REG.' + T.reg + '.lead tops out at ' + R.lead[1] + ' (< 72, the cluster gate)');
    }
    var E = ENSEMBLES[T.ens] || {}, bands = Object.keys(E);
    if (bands.length > 4) bad.push('ENSEMBLES.' + T.ens + ' declares ' + bands.length + ' bands; A9 caps it at 4');
    for (j = 0; j < bands.length; j++) {
      var band = E[bands[j]];
      for (k in band) {
        if (k === 'credit') continue;
        var p = band[k];
        /* a role may now name a STACK — a multi-layer patch defined in
           k07-band — instead of a single [engine, patch] pair. Both are
           checked; what is not allowed is a name that resolves to neither. */
        if (typeof p === 'string') {
          if (typeof STACKS === 'undefined' || !STACKS[p])
            bad.push('ENSEMBLES.' + T.ens + '.' + bands[j] + '.' + k + ' names stack "' + p + '", which does not exist');
          continue;
        }
        if (!p || p.length !== 2) { bad.push('ENSEMBLES.' + T.ens + '.' + bands[j] + '.' + k + ' is not an [engine,patch] pair'); continue; }
        if (p[0] === 'fm' && p[1] === 'fmBass') bad.push('ENSEMBLES.' + T.ens + '.' + bands[j] + '.' + k + ' names fm/fmBass, banned by RING 18');
        if (!PATCHES[p[0]] || !PATCHES[p[0]][p[1]]) bad.push('ENSEMBLES.' + T.ens + '.' + bands[j] + '.' + k + ' = ' + p[0] + '/' + p[1] + ', which PATCHES does not have');
      }
      if (!band.credit) bad.push('ENSEMBLES.' + T.ens + '.' + bands[j] + ' has no credit line');
    }
    if (!T.origin) bad.push(nm + ' has no origin line');
  }
  return bad;
}

