/* the catalog checks itself at load, on the six rules FORMAT.md sets out */
function figCheck() {
  var ids = Object.keys(FIG), i, k, bad = [];
  for (i = 0; i < ids.length; i++) {
    var f = FIG[ids[i]], id = ids[i];
    if (f.grid !== 12 && f.grid !== 16 && f.grid !== 24) bad.push(id + ": grid " + f.grid);
    if (f.verify !== "transcribed" && f.verify !== "derived" && f.verify !== "uncertain") bad.push(id + ": verify " + f.verify);
    if (!f.from) bad.push(id + ": no provenance");
    var flat = 1, v0 = f.hits[0][1], last = -1;
    for (k = 0; k < f.hits.length; k++) {
      var h = f.hits[k];
      if (h[0] < 0 || h[0] >= f.grid * 2) bad.push(id + ": pulse " + h[0] + " outside grid " + f.grid);
      if (h[0] < last) bad.push(id + ": out of time order at " + h[0]);
      last = h[0];
      if (!(h[1] > 0 && h[1] <= 1)) bad.push(id + ": velocity " + h[1]);
      if (h[1] !== v0) flat = 0;
    }
    if (flat && f.hits.length > 2) bad.push(id + ": flat velocity");
    if (f.also) for (k = 0; k < f.also.length; k++) {
      var oid = f.also[k].split(/[+-]/)[0];
      if (!FIG[oid]) bad.push(id + ": declares a relation to " + oid + ", which does not exist");
    }
  }
  return bad;
}
(function () { var b = figCheck(); if (b.length) throw new Error("figure catalog: " + b.slice(0, 5).join("; ")); })();
function figHits(id) { var f = FIG[id]; return f ? f.hits : null; }

