  if (wrong) throw new Error('feel: readback failed on ' + wrong + '/' + ev.length + ' hits — the figure cannot be read off the performance');
  if (moved < ev.length * 0.95) throw new Error('feel: only ' + moved + '/' + ev.length + ' hits moved — the pass is not doing anything');
  /* the realised sigma must BE the budget, not a fraction of it */
  var dv = [], dm = 0;
  for (i = 0; i < ev.length; i++) { var d = 20 * Math.log(ev[i].vel / written[i]) / Math.LN10; dv.push(d); dm += d; }
  dm /= dv.length;
  var ds = 0; for (i = 0; i < dv.length; i++) ds += (dv[i] - dm) * (dv[i] - dm);
  ds = Math.sqrt(ds / dv.length);
