  'analog/lead':4.408, 'analog/pad':5.308, 'analog/pluckS':10.286,
  'analog/reso':4.91, 'bowed/cello':0.771, 'bowed/sul':1.39,
  'bowed/tasto':0.388, 'bowed/violinS':0.717, 'fm/brassy':0.378,
  'fm/chime':1.134, 'fm/ebell':0.639, 'fm/epMark':0.532, 'fm/fmBass':0.752,
  'fm/glassPad':0.458, 'fm/marim':0.734, 'fm/wire':0.965, 'kit/afroK':1.247,
  'kit/boombap':0.821, 'kit/cine':1.044, 'kit/ewf':1.065, 'kit/houseK':0.873, 'kit/hyphyK':0.65,
  'kit/latinK':1.459, 'kit/neptune':0.888, 'kit/softK':3.289,
  'kit/timb':1.123, 'kit/trapK':1.133, 'mallet/bells':0.601,
  'mallet/glassM':0.714, 'mallet/glock':0.715, 'mallet/kalimba':0.709,
  'mallet/marimba':0.655, 'mallet/tubular':0.69, 'mallet/vibes':0.844,
  'mallet/vibesFl':0.687, 'mallet/woodM':0.586, 'organ/bassOrg':0.462,
  'organ/church':0.43, 'organ/full':0.322, 'organ/jazz':0.417,
  'organ/thin':0.536, 'perc/afroP':0.801, 'perc/brightP':1.115,
  'perc/deepP':0.727, 'perc/handP':1.095, 'perc/latinP':0.926,
  'pluck/bassGt':5.858, 'pluck/clav':4.71, 'pluck/gong':5.508,
  'pluck/harp':5.046, 'pluck/koto':4.597, 'pluck/nylon':3.983,
  'pluck/pianoS':5.927, 'pluck/steel':6.201, 'solina/brassEn':3.338,
  'solina/swell':5.575, 'solina/viola':3.787, 'solina/violin':3.32,
  'station/airy':6.305, 'station/bassSt':3.934, 'station/digiKey':5.761,
  'station/dream':2.564, 'station/stab':3.91, 'station/sweeper':3.547,
  'station/workPad':4.171, 'tine/bellEP':1.187, 'tine/bright':1.676,
  'tine/dark':1.05, 'tine/mark':1.227, 'tine/wurli':1.811, 'vox/aahs':10.363,
