/* a spec is either [engine, patch] or a stack name */
function isStack(spec) { return typeof spec === 'string' && !!STACKS[spec]; }

var K_ENSEMBLES = {
  knock:    [{ keys: ['station', 'stab'], lead: 'bell', pad: ['station', 'airy'], credit: 'Bay Area — thin synth stabs over the 808, nothing competing with the low end' }],
  crunk:    [{ keys: ['organ', 'thin'], lead: ['analog', 'lead'], pad: ['solina', 'swell'], credit: 'Atlanta crunk — the organ line and a lead that shouts' }],
  bounce:   [{ keys: ['station', 'digiKey'], lead: ['vox', 'solo'], pad: ['vox', 'oohs'], credit: 'New Orleans bounce — the chant is the melody' }],
  miami:    [{ keys: ['analog', 'reso'], lead: ['analog', 'lead'], pad: ['solina', 'brassEn'], credit: 'electro — the resonant analogue riff after "Planet Rock"' }],
  dembow:   [{ keys: ['organ', 'thin'], lead: 'bell', pad: ['solina', 'swell'], credit: 'dembow — the organ skank and a bright hook' }],
  drill:    [{ keys: ['mallet', 'bells'], lead: ['pluck', 'nylon'], pad: ['station', 'airy'], credit: 'UK drill — bell figure and a nylon guitar over static harmony' },
             { keys: 'bell', lead: ['mallet', 'glock'], pad: ['vox', 'whisper'], credit: 'drill — the glassy bell school' }],
  trap:     [{ keys: ['mallet', 'bells'], lead: 'bell', pad: ['station', 'airy'], credit: 'trap — the bell melody that carries the whole record' },
             { keys: ['pluck', 'harp'], lead: ['mallet', 'glock'], pad: ['solina', 'swell'], credit: 'trap — the harp-and-glock school' }],
  foot:     [{ keys: ['tine', 'mark'], lead: ['vox', 'solo'], pad: ['station', 'airy'], credit: 'footwork — a chopped Rhodes and a chopped voice' }],
  gogo:     [{ keys: ['organ', 'jazz'], lead: 'brass', pad: ['organ', 'full'], credit: 'go-go — Chuck Brown’s guitar and the horn section' }],
  line:     [{ keys: ['organ', 'church'], lead: 'brass', pad: ['solina', 'brassEn'], credit: 'second line — the brass band, trumpet on top' }],
  jungle:   [{ keys: ['station', 'workPad'], lead: ['mallet', 'vibes'], pad: ['station', 'airy'], credit: 'jungle — the rave stab and a vibraphone over the Amen' }],
  piano:    [{ keys: ['tine', 'mark'], lead: ['mallet', 'marimba'], pad: ['vox', 'aahs'], credit: 'amapiano — Rhodes and the log drum’s melodic cousin' },
             { keys: ['organ', 'church'], lead: ['vox', 'solo'], pad: ['solina', 'swell'], credit: 'amapiano ← marabi — the shebeen organ' }],
  batucada: [{ keys: ['pluck', 'nylon'], lead: ['vox', 'solo'], pad: ['solina', 'violin'], credit: 'samba — the nylon guitar and the singer' }],
  bell:     [{ keys: ['vox', 'aahs'], lead: ['mallet', 'kalimba'], pad: ['vox', 'oohs'], credit: 'the 12/8 ensemble — chorus in parallel fourths, kalimba answering' }],
  bembe:    [{ keys: ['vox', 'oohs'], lead: ['vox', 'solo'], pad: ['vox', 'aahs'], credit: 'the bembé coro — everything is a voice, because everything was' },
             { keys: ['pluck', 'nylon'], lead: ['mallet', 'marimba'], pad: ['vox', 'oohs'], credit: 'the folkloric set as a Havana studio recorded it — tres and marimbula' }],
  tiriba:   [{ keys: ['pluck', 'steel'], lead: ['pluck', 'nylon'], pad: ['organ', 'full'], credit: 'the highlife front line — steel-string lead, nylon rhythm, organ underneath' },
             { keys: ['pluck', 'nylon'], lead: 'brass', pad: ['organ', 'jazz'], credit: 'the dance-band version — horns take the line off the guitar' }],
  agbadza:  [{ keys: ['vox', 'aahs'], lead: ['vox', 'solo'], pad: ['vox', 'oohs'], credit: 'the Ewe chorus — a lead singer and everyone answering, which is the whole instrumentation above the drums' }],
  soli:     [{ keys: ['mallet', 'marimba'], lead: ['vox', 'solo'], pad: ['vox', 'aahs'], credit: 'balafon and voice — the initiation ensemble, where the melody is struck wood' }],
  sorso:    [{ keys: ['mallet', 'kalimba'], lead: ['mallet', 'marimba'], pad: ['vox', 'aahs'], credit: 'Baga tuned percussion — the melody lives on struck wood and metal' }],
  kple:     [{ keys: ['pluck', 'steel'], lead: ['pluck', 'nylon'], pad: ['organ', 'full'], credit: 'palm-wine guitars — two of them, in thirds, exactly as the Accra bands played' },
             { keys: ['organ', 'full'], lead: ['pluck', 'steel'], pad: ['solina', 'swell'], credit: 'the 1970s Accra band — organ carries the chord, guitar answers' }],
  house:    [{ keys: ['organ', 'jazz'], lead: ['analog', 'lead'], pad: ['solina', 'swell'], credit: 'deep house — the organ chord and a filtered lead' },
             { keys: ['tine', 'bright'], lead: 'bell', pad: ['station', 'airy'], credit: 'house — the Rhodes school' }],
  bap:      [{ keys: ['tine', 'dark'], lead: ['mallet', 'vibes'], pad: ['solina', 'swell'], credit: 'boom bap — the dusty Rhodes and a vibraphone' }],
  funk:     [{ keys: ['pluck', 'clav'], lead: 'brass', pad: ['organ', 'full'], credit: 'funk — the clavinet and the horn line' }]
};

/* melodic channel strips for the drum room. The drums own the bottom, so
   everything melodic here is high-passed harder than it would be in a
   melodic-first mix, and the keys sit out of the 808's way on purpose. */
function kmStrip(role, c) {
  switch (role) {
    case 'keys': return { hp: 190, loHz: 300, lo: -1.4, midHz: 900, midQ: 1.0, mid: 0.4,
                          hiHz: 5200, hi: 2.0, drive: 1.12, bias: 0.24, atk: 0.28, width: 1.18 };
    case 'lead': return { hp: 220, loHz: 340, lo: -1.0, midHz: 1200, midQ: 0.9, mid: 1.0,
                          hiHz: 5200, hi: 2.6, drive: 1.2, bias: 0.3, atk: 0.3, width: 1.06 };
    default:     return { hp: 240, loHz: 380, lo: -2.4, midHz: 700, midQ: 0.9, mid: -1.6,
                          hiHz: 6000, hi: 2.2, drive: 1.05, bias: 0.18, atk: 0, width: 1.42 };
  }
}

/* `bass` is APPENDED, never inserted: MEL_LANES.indexOf salts every melodic
   stream, so putting it anywhere but the end would re-seed keys, lead and pad
   and move every world that already exists. */
var MEL_LANES = ['keys', 'lead', 'pad', 'bass'];

/* ── buildBand ─────────────────────────────────────────────────────────────
   A number in, a whole band out, in the shape buildWorld and buildBeat both
   return — so the engine, transport, exporter and stems play it with no
   change at all. "A song is a world", one more time.

   THE DICE CONTRACT, extended. k05's law is one stream per lane, and it holds
   for every melodic lane here. It cannot hold for HARMONY, because the chord
   is a shared object every part reads — so harmony draws from a stream salted
   by NEITHER lane nor roll, exactly the way the drummer's dropout bars do,
   and gets its own die. Rolling harmony moves every melodic part's PITCHES
   and leaves every rhythm and ENTRANCE byte-identical; rolling a part leaves
   the harmony byte-identical.

   The contract is stated on ONSETS, not on the event list, and the difference
   matters. A minor seventh has four notes and a triad has three, so a harmony
   roll legitimately changes how many events land at one instant — comparing
   flat event lists reads that as "the times moved" when every onset is
   identical to the last decimal, and it cost three measurements before the
   distinction was drawn. Measured the right way: 20 of 20 seeds keep every
   distinct onset, and 0 of 20 disturb the drums at all. */
