  this.miss[k] = (this.miss[k] || 0) + 1;
  if (this.miss[k] >= 2) { this.spent[k] = this.last.dir; this.miss[k] = 0; }
  if (this.step[k] < 0.03) this.frozen[k] = 1;      /* out of resolution */
  this.history.push({ gen: this.gen, trait: k, to: this.last.from, verdict: 'not that' });
  this.gen++; this.rejected++;
